mapper.select:
SELECT vi.video_id, vi.video_cover, vi.video_name, vi.user_id, vi.create_time, vi.last_update_time, vi.p_category_id, vi.category_id, vi.tags, vi.introduction, vi.interaction, vi.duration, vi.play_count, vi.recommend_type, vi.recommend_time, vi.is_public, vi.is_vip, vi.audit_status, vi.is_deleted, u.nick_name, vf.file_id FROM video_info vi LEFT JOIN user_info u ON vi.user_id COLLATE utf8mb4_unicode_ci = u.user_id LEFT JOIN video_info_file vf ON vi.video_id = vf.video_id AND vf.file_index = 0 WHERE vi.is_deleted = 0
AND vi.video_name LIKE CONCAT('%', #{dto.videoName}, '%')
AND vi.category_id = #{dto.categoryId}
AND vi.audit_status = #{dto.auditStatus}
AND vi.recommend_type = #{dto.recommendType}
AND vi.is_vip = #{dto.isVip}
ORDER BY vi.create_time DESC
